import heapq

# Tasks: (ID, duration)
tasks = {
    'T1': 2,
    'T2': 3,
    'T3': 1,
    'T4': 2
}

# Precedences: T1 -> T3; T2 -> T3; T2 -> T4
precedences = {
    'T3': ['T1', 'T2'],
    'T4': ['T2']
}

# Track dependencies remaining for each task
in_degree = {t: len(precedences.get(t, [])) for t in tasks}
# Track which tasks are unlocked by completing a specific task
successors = {t: [] for t in tasks}
for target, sources in precedences.items():
    for source in sources:
        successors[source].append(target)

# Initial available tasks (no dependencies)
available = [t for t in tasks if in_degree[t] == 0]
heapq.heapify(available) # Using heap to manage workers, though simple list works here

# Workers: (finish_time, task_id)
workers = []
current_time = 0

while available or workers:
    # Assign tasks to available workers
    while available and len(workers) < 2:
        task_id = heapq.heappop(available)
        heapq.heappush(workers, (current_time + tasks[task_id], task_id))

    # Advance time to the next worker finishing
    if workers:
        current_time, finished_task = heapq.heappop(workers)
        # Update dependencies
        for succ in successors[finished_task]:
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                heapq.heappush(available, succ)

        # Check if other workers finish at the same time
        while workers and workers[0][0] == current_time:
            _, f_task = heapq.heappop(workers)
            for succ in successors[f_task]:
                in_degree[succ] -= 1
                if in_degree[succ] == 0:
                    heapq.heappush(available, succ)

print(f"Minimum completion time: {current_time}")

